          ..write('data: ')
          ..write(
            jsonEncode({
              'id': 'mock',
              'object': 'chat.completion.chunk',
              'choices': [
                {
                  'delta': {'content': chunk},
                  'index': 0,
                },
              ],
            }),
          )
          ..write('\n\n');
      }
      body_
        ..write('data: ')
        ..write(
          jsonEncode({
            'id': 'mock',
            'object': 'chat.completion.chunk',
            'choices': [
              {'delta': {}, 'finish_reason': 'stop', 'index': 0},
            ],
          }),
        )
        ..write('\n\ndata: [DONE]\n\n');
      res.add(utf8.encode(body_.toString()));
      await res.close();
    }
  }
}

