  FaCliHarness harness,
  Directory home,
  int messageIndex,
) async {
  printOnFailure('=== WEDGE FORENSICS (message #$messageIndex) ===');
  try {
    final pgrep = await Process.run('pgrep', ['-f', 'bin/fah.dart']);
    final pids = (pgrep.stdout as String)

