        for (var i = 1; i <= 6; i++) {
          final n = batch * 10 + i;
          await peer.sendDm(cliAgentId, 'сообщение #$n — ответь коротко');
          await expectMarker('Ответ #$n.');
          await Future<void>.delayed(const Duration(seconds: 2));
